var e={"browser.title":`ブラウザ`,"browser.menu":`ブラウザ…`,"browser.sectionDesc":`API のないサイト向けに、このサーバー上で動く Chromium です。ページを開き、クリックし、フォームに入力します。ページで必要なときだけ使われます。`,"browser.topicTitle":`Harness Browser · {name}`,"browser.topicDesc":`このトピックのセッションが Harness Browser を使えるかどうかを設定します（プロジェクトのプロファイル、つまりログイン済みのアカウントと接続を使用）。Claude はまず、より簡単なツールでページを読みます。`,"browser.dialogDesc":`Harness Browser のライブ表示です。タブの中で自分でクリックや入力ができます（CAPTCHA やログインなど）。Claude に求められたら、操作を Claude に戻してください。`,"browser.enable":`Harness Browser を使用可能にする`,"browser.enableDesc":`このセッションがブラウザでページを開けるようになります。継承：プロジェクトの設定に従います。`,"browser.featureOff":`このサーバーでは Harness Browser がオフになっています。`,"browser.openFeatures":`設定 → 機能`,"browser.notReady":`このサーバーはまだブラウザの準備ができていません`,"browser.notReadyDesc":`不足しているもの：{missing}。セットアップでインストールされます（数分、1 回のみ）。`,"browser.setup":`セットアップ`,"browser.more":`その他の設定`,"browser.ask":`行き詰まったら確認する`,"browser.askDesc":`CAPTCHA、サインイン、コードなどが必要な場合は、自分で試さず、通知や Telegram でお知らせして待機します。`,"browser.wait":`待機する時間`,"browser.waitDesc":`それまでに返答がない場合は、その手順を省いて続行します。`,"browser.minutes":`{count}分`,"browser.hours":`{count}時間`,"browser.downloads":`ダウンロードを許可`,"browser.downloadsDesc":`ファイルはワークスペースの downloads/browser に保存されます。オフの場合、ダウンロードは拒否されます。`,"browser.forget":`サインイン情報を消去`,"browser.forgetDesc":`このプロファイルのサインイン情報（Cookie）、タブ、操作の履歴を消去します。`,"browser.forgetTitle":`サインイン情報を消去しますか？`,"browser.forgetConfirm":`このプロファイルのサインイン情報、タブ、履歴が消去されます。再度サインインが必要になります。`,"browser.back":`戻る`,"browser.forward":`進む`,"browser.reload":`再読み込み`,"browser.address":`アドレス`,"browser.page":`ページ`,"browser.notRunning":`停止中`,"browser.claudeDriving":`Claude が使用中`,"browser.starting":`ブラウザーを起動しています…`,"browser.loading":`ページを読み込んでいます…`,"browser.idle":`Claude が必要としたとき、またはここから起動します。`,"browser.connecting":`接続しています…`,"browser.open":`ブラウザーを開く`,"browser.stop":`停止`,"browser.typeHere":`ページにテキストを入力`,"browser.typeSend":`入力する`,"browser.blocked":`ブロックされたアドレス：{count}件`,"browser.blocked#one":`ブロックされたアドレス：1件`,"browser.ask.title":`Claude からのお願い：`,"browser.ask.skip":`スキップ`,"browser.bar.on":`Claude がブラウザーを使用中`,"browser.bar.watch":`見る`,"browser.newTab":`新しいタブ`,"browser.minimize":`最小化（ブラウザーは動き続けます）`,"browser.ask.whoNeeds":`{name} からのお願い：`,"browser.handBackToClaude":`Claude に操作を戻す`,"browser.clickToTake":`クリックして操作を引き継ぐ`,"browser.openWindow":`ブラウザーを開く`,"browser.ask.note":`Claude へのメモ（任意）`,"browser.agentAsks":`{name} がブラウザーでの操作を求めています`,"browser.feature.title":`Harness Browser`,"browser.feature.desc":`API のないサイト向けに、あなた、セッション、エージェントが使える、このサーバー上の Chromium です。プロファイルごとにサインイン情報を分けて保持でき、別のアドレス（お使いのスマートフォンやレンタルのプロキシ）経由で接続することもできます。音は出ず、拡張機能もありません。普段使いのブラウザーではありません。`,"browser.feature.enable":`Harness Browser`,"browser.feature.enableDesc":`有効にすると、すべてのセッションで使えます（プロジェクトやトピックは無効にできます：そのメニュー → ブラウザー）。エージェントは、オンにしたときに使えます（その設定 → ブラウザー）。`,"browser.feature.idle_min":`プロファイルがスリープするまで`,"browser.feature.idleDesc":`見ている人も、セッションも、リクエストもない場合です。タブは、次回の起動時にスリープ状態で復元されます。`,"browser.feature.tab_sleep_min":`タブがスリープするまで`,"browser.feature.tabSleepDesc":`使われていないタブは閉じて保存されます。クリックすると再び開きます。`,"browser.feature.max_tabs":`同時に起動するタブの上限`,"browser.feature.maxTabsDesc":`上限を超えると、最も古いタブがスリープします。タブごとにサーバーのメモリを使用します。`,"browser.settingsDesc":`ブラウザー、そのプロファイルと接続の設定です。`,"browser.name":`Harness Browser`,"browser.tabs":`タブ`,"browser.signins.label":`プロファイル`,"browser.signins.desc":`既定ではプロジェクトのプロファイルを使います。プロジェクトの他のエージェントやセッションと同じサインイン情報です。`,"browser.signins.inherit":`プロジェクトのプロファイル（{name}）`,"browser.card.asleep":`エージェントが使うときに起動します`,"browser.asleepTitle":`スリープ中`,"browser.profile.web":`公開されているサイトはすべて開けます。このサーバーやローカルネットワークのアドレスはブロックされたままで、サンドボックス内のエージェントは許可されたドメインのみ開けます（そのページ → 保護）。`,"browser.card.domains":`許可されたドメインのみ（{count}件）`,"browser.card.domains#one":`許可されたドメインのみ（1件）`,"browser.card.noDomain":`ドメインなし：サンドボックス内では、ブラウザーは何も開けません`,"browser.card.waits":`あなたを待っています`,"browser.card.noTab":`開いているタブはありません`,"browser.feature.search":`検索エンジン`,"browser.feature.searchDesc":`アドレスバーでの検索に使うエンジンです。Google は、Claude が操作するブラウザーにロボットでないことの確認を求める場合があります。DuckDuckGo と Bing では求められません。`,"browser.addressHint":`検索またはアドレスを入力`,"browser.dialog.title":`このページからのメッセージ`,"browser.dialog.leave":`このページから移動しますか？入力した内容が保存されない可能性があります。`,"browser.dialog.leaveOk":`移動する`,"browser.chooser.one":`ページがファイルを求めています。`,"browser.chooser.many":`ページが複数のファイルを求めています。`,"browser.chooser.pick":`ファイルを選択`,"browser.chooser.failed":`ファイルをページに渡せませんでした`,"browser.youHaveTab":`このタブはあなたが操作中です。Claude は操作が戻されるまで待機します。`,"browser.ntp.desc":`普段使いのブラウザーではありません。Claude が作業するサイトとサインイン情報のためのものです。音は出ず、拡張機能もありません。`,"browser.memTitle":`このサーバー上のブラウザーのメモリ`,"browser.tabsAwake":`開いているタブ：{count}個`,"browser.tabsAwake#one":`開いているタブ：1個`,"browser.sleepTabs":`タブをスリープさせる`,"browser.by.agent":`エージェント {name} が開きました`,"browser.by.session":`セッションが開きました`,"browser.by.you":`あなたが開きました`,"browser.asleep":`スリープ中：クリックすると再び開きます`,"browser.closeTab":`タブを閉じる`,"browser.openPage":`ブラウザ設定`,"browser.openPageHint":`ブラウザ、プロファイル、接続：設定 → ブラウザ。`,"browser.profilesDesc":`プロファイルは、ログイン済みのアカウントと接続を個別に保持します。「一般」はあなた用（およびプロジェクト general と system 用）で、その他のプロジェクトにはそれぞれ専用のプロファイルがあります。`,"browser.exitsDesc":`ページの通信の出口：このサーバー、スマートフォン、ルーター、レンタルのプロキシ。`,"browser.behaviour":`仕組み`,"browser.bar.tabs":`このセッションのタブが{count}個開いています`,"browser.bar.tabs#one":`このセッションのタブが1個開いています`,"browser.bar.hide":`非表示`,"browser.memWarn":`このサーバーのメモリが不足しています。ブラウザのタブをスリープさせてください。`,"browser.sleepShort":`スリープ`,"browser.profiles":`プロファイル`,"browser.domain.out":`{host} は {name} のドメインに含まれていません。自動実行によってこのタブが空になります（Claude とのやり取りは消えません）。`,"browser.domain.add":`ドメインに追加`,"browser.domain.agent":`このエージェント`,"browser.mine.asleep":`開くか、Claude が必要としたときに起動します`,"browser.mine.noPage":`開いているページはありません`,"browser.mine.desc":`このコンピューターではなく、お使いのサーバー上で動く本物の Chromium です。ログインしたアカウントはそこに残り、ブラウザを許可したセッションやエージェントで Claude が利用できます。`,"browser.mine.profileHint":`プロファイルでログイン済みのアカウントを選びます。プロジェクトのプロファイルは、そのセッションやエージェントと共有されます。`,"browser.mine.connection":`接続`,"browser.mine.connectionHint":`サイトから見えるアドレス：サーバー、スマートフォン、プロキシ、WireGuard ボックスのいずれか。`,"browser.mine.open":`自分のブラウザを開く`,"browser.mine.agents":`エージェントのブラウザ`,"browser.mine.noAgents":`ブラウザを持つエージェントはまだありません`,"browser.mine.noAgentsHow":`エージェントを開く → 設定 → ブラウザ：プロジェクトのプロファイルが使われ、ここで作業の様子を見られます。`,"browser.mine.toAgents":`エージェントへ移動`,"browser.persistentNone":`このプロファイルを使うエージェントはありません`,"browser.temporaryNone":`セッションのブラウザはまだありません`,"browser.mine.ready":`起動中・ページなし`,"browser.mine.agentsDesc":`ブラウザを持つエージェントは、それぞれ専用のウィンドウをプロジェクトのプロファイルで常時保持します。`,"browser.side.browser":`自分のブラウザ`,"browser.profile.add":`プロファイルを追加`,"browser.profile.ofProject":`プロジェクト {name}`,"browser.profile.yours":`あなた用`,"browser.profile.agentsOne":`エージェント1件`,"browser.profile.agentsMany":`エージェント{count}件`,"browser.profile.projectGone":`プロジェクトは削除されました`,"browser.profile.rename":`プロファイル名を変更`,"browser.profile.projectKeep":`プロジェクトのプロファイルは、プロジェクトが存在する間は残ります。最初からやり直すには、ログイン済みのアカウントを削除してください。`,"browser.persistent":`常駐`,"browser.persistentDesc":`エージェントごとに1つのブラウザが常時あります。このプロファイルのログイン情報を共有します。`,"browser.persistentEmpty":`エージェントを開く → 設定 → ブラウザ：プロジェクトのプロファイルが使われます（またはそこでこのプロファイルを選択）。それぞれ専用のウィンドウがここに常時表示されます。`,"browser.persistentYou":`あなたのブラウザはこのプロファイルを使っています。`,"browser.temporary":`一時`,"browser.temporaryDesc":`セッションが開くブラウザです。セッションが使わなくなると閉じ、この行だけが残ります。`,"browser.temporaryEmpty":`このプロジェクトのセッションは、Claude が必要としたときにブラウザを開きます。セッションが使わなくなると閉じ、ここに1行残ります。`,"browser.temp.session":`セッション`,"browser.temp.topic":`トピック`,"browser.temp.sites":`サイト`,"browser.temp.when":`日時`,"browser.temp.duration":`時間`,"browser.temp.watch":`見る`,"browser.temp.untitled":`無題のセッション`,"browser.connection":`接続`,"browser.connection.seen":`サイトから見えるIP：{ip}`,"browser.connection.untested":`未テストです。接続を開いてテストしてください。`,"browser.connection.checking":`接続を確認中…`,"browser.connection.shared":`接続はプロファイルに属します。ここで変更すると、そのエージェントとセッションにも反映されます。`,"browser.directWarn":`お使いのサーバーにはデータセンターのアドレスが割り当てられており、一部のサイトにブロックされたり検知されたりします。スマートフォン、自宅のルーター、プロキシ経由のほうが目立たず安全です。`,"browser.panel.projectProfile":`そのセッションはプロジェクトのプロファイル（{name}）を使います。`,"browser.agent.profile":`ブラウザのプロファイル`,"browser.exits":`接続`,"browser.mainProfile":`一般`,"browser.paused":`一時停止中`,"browser.nav.me":`自分のブラウザ`,"browser.nav.session":`セッション`,"browser.nav.acting":`Claude が操作中`,"browser.menu.title":`ブラウザ設定`,"browser.menu.signins":`プロファイル`,"browser.menu.ofFolder":`フォルダのもの`,"browser.menu.search":`検索エンジン`,"browser.menu.picture":`画質`,"browser.menu.manage":`プロファイルと接続…`,"browser.quality.auto":`自動`,"browser.quality.autoDesc":`ネットワークに合わせます。遅いときは軽くなります`,"browser.quality.low":`スムーズ`,"browser.quality.lowDesc":`小さい画像を多く送ります（遠距離または低速のネットワーク向け）`,"browser.quality.high":`高精細`,"browser.quality.highDesc":`最も鮮明な画像（高速ネットワーク向け）`,"browser.profilesOn":`プロファイル{count}件`,"browser.defaults":`デフォルト`,"browser.on":`オン`,"browser.off":`オフ`,"browser.inheritSwitch":`継承（{state}、{from}から）`,"browser.enableDescProject":`トピックとそのセッションが利用できます（トピック側で別の指定がある場合を除く）。エージェントは常に自分で選択します。`,"browser.enableDescAgent":`エージェントごとに、デフォルトではオフです。実行や会話の中でブラウザのページを開けるようになります。`,"browser.projectTitle":`Harness Browser · {name}`,"browser.projectDesc":`個別に設定していないこのプロジェクトのすべてのトピックについて、セッションがブラウザを使えるかどうかと、使うプロファイルを決めます。`,"browser.ownerLine":`プロファイル {profile} · 接続 {exit} · {line}`,"browser.pace":`{fps} 枚/秒 · {kb} KB`,"browser.paceDelay":`{ms} ms で反応`,"browser.paceTitle":`ライブビューの滑らかさ`,"browser.down.title":`接続 {name} が切断されています：`,"browser.down.desc":`Claude はサーバーのアドレスから外に出ず、停止しました。`,"browser.down.resumeOn":`接続が戻ると、Claude は自動で再開します。`,"browser.down.resume":`接続が戻ったら再開`,"browser.down.retry":`今すぐ再試行`,"browser.down.open":`接続を開く`,"browser.feature.max_active_profiles":`同時に起動するプロファイル数`,"browser.feature.maxProfilesDesc":`各プロファイルはそれぞれ独立した Chromium です。上限を超えると、最も長く使われていないものがスリープします。`,"browser.feature.exit_wait_s":`切断された接続を待つ時間`,"browser.feature.exitWaitDesc":`その後 Claude は停止し、通知が届きます。サーバーのアドレスから自動で外に出ることはありません。`,"browser.profile.newDesc":`専用の Chromium で、ログイン状態と接続を個別に持ちます。各プロジェクトにはすでに1つあります。追加のプロファイルは、分けておきたいエージェント用です。`,"browser.profile.namePh":`ショップ、クライアント Acme…`,"browser.profile.create":`作成`,"browser.profile.down":`接続が切断されたとき`,"browser.profile.downWait":`待機して通知する`,"browser.profile.downVps":`サーバーのアドレスから出る`,"browser.profile.downWaitHint":`推奨：サイトに、ログインが別のアドレスから来たように見えることはありません。`,"browser.profile.downVpsHint":`このプロファイルのサイトにデータセンターのアドレスが見え、追加の確認を求められることがあります。`,"browser.profile.memory":`メモリ`,"browser.profile.on":`起動中 · {tabs} 個のタブを開いています · {mem}`,"browser.profile.off":`スリープ中 · {tabs} 個のタブを保持`,"browser.profile.sleep":`スリープ`,"browser.profile.danger":`ログイン状態`,"browser.profile.delete":`プロファイルを削除`,"browser.profile.deleteTitle":`{name} を削除しますか？`,"browser.profile.deleteDesc":`ログイン状態とタブが消去されます。エージェントはプロジェクトのプロファイルに戻ります。`,"browser.profile.settings":`プロファイル設定`,"browser.profile.settingsLink":`プロファイル設定`,"browser.exit.add":`接続を追加`,"browser.exit.addTitle":`接続を追加`,"browser.exit.direct":`サーバーの IP`,"browser.exit.directLine":`このサーバーのアドレス`,"browser.exit.directDesc":`ページはこのサーバー自身のアドレス（データセンターのアドレス）から出ます。ほとんどのサイトでは問題ありませんが、一部（ショップ、SNS）では追加の確認を求められたり、ブロックされたりします。`,"browser.exit.down":`オフライン`,"browser.exit.downSince":`{min} 分間オフライン`,"browser.exit.untested":`未テスト`,"browser.exit.checking":`確認中…`,"browser.exit.name":`名前`,"browser.exit.kind.proxy":`レンタルプロキシ`,"browser.exit.kind.tailscale":`自分のスマートフォン`,"browser.exit.kind.wireguard":`WireGuard`,"browser.exit.state.up":`動作中`,"browser.exit.state.down":`オフライン`,"browser.exit.state.unknown":`未確認`,"browser.exit.usedBy":`使用中：{names}`,"browser.exit.unused":`まだどのプロファイルも使用していません。プロファイルの設定で選択してください。`,"browser.exit.delete":`接続を削除`,"browser.exit.deleteTitle":`{name} を削除しますか？`,"browser.exit.deleteDesc":`パスワードまたは設定が保管庫から削除されます。`,"browser.exit.toolsTitle":`このサーバーにツールが不足しています`,"browser.exit.toolsDesc":`セットアップでは、ブラウザ専用に Tailscale と wireproxy をインストールします（1回、約1分）。サーバーのそれ以外の部分では使用されません。`,"browser.add.why":`サイトには、ページの接続元のアドレスが見えます。このサーバーのアドレスはデータセンターのもので、追加の確認を求めたり、拒否したりするサイトがあります。接続を追加すると、ブラウザのページだけが別の場所から出ます。`,"browser.add.never":`外に出るのはブラウザだけです。セッション、エージェント、サーバーのそれ以外の部分はサーバーのアドレスのままです。名前の解決はサーバー上で行われるため、接続からローカルネットワークに届くことはありません。`,"browser.add.recommended":`推奨`,"browser.add.soon":`近日対応`,"browser.add.tailscale.title":`自分のスマートフォン（Tailscale）`,"browser.add.tailscale.desc":`ページはスマートフォンの4G回線または自宅の回線から出ます。普段使いの本物のアドレスです。`,"browser.add.tailscale.needs":`iPhone、Android スマートフォン、または常時起動のパソコンと、無料の Tailscale アカウントが必要です。`,"browser.add.proxy.title":`レンタルプロキシ`,"browser.add.proxy.desc":`プロバイダーから借りた、住宅用または ISP のプロキシです。選んだ国のアドレスを使えます。`,"browser.add.proxy.needs":`アドレス（socks5:// または http://）、ユーザー、パスワードが必要です。`,"browser.add.wireguard.title":`WireGuard`,"browser.add.wireguard.desc":`お持ちのルーター（Fritz!Box、ホームルーター、OpenWrt）、または WireGuard ファイルを提供する VPN を使います。`,"browser.add.wireguard.needs":`WireGuard の設定ファイルが必要です。`,"browser.add.pc.title":`自分のパソコン`,"browser.add.pc.desc":`ページは作業に使っているパソコンから出ます。`,"browser.add.pc.needs":`パソコンに小さなプログラムをインストールする必要があります。`,"browser.test.run":`テスト`,"browser.test.hint":`サイトに見えるアドレス、その種類、遅延、速度を表示します。`,"browser.test.failed":`テストに失敗しました：{why}`,"browser.test.kind.mobile":`モバイル`,"browser.test.kind.isp":`自宅 / ISP`,"browser.test.kind.hosting":`データセンター`,"browser.test.delay":`{ms} ms`,"browser.test.speed":`{mbps} Mbit/s`,"browser.test.hostingWarn":`サイトにはデータセンターのアドレスが見えます。この接続は、サーバーをブロックするサイトには役立ちません。`,"browser.proxy.desc":`プロバイダーから提供されるアドレスです（socks5://host:port または http://host:port）。パスワードはボールトに保存されます。`,"browser.proxy.url":`アドレス`,"browser.proxy.user":`ユーザー`,"browser.proxy.password":`パスワード`,"browser.proxy.kept":`保管庫に保存済み`,"browser.proxy.vault":`パスワードは設定 → キーに保存され、設定には保存されません。`,"browser.wireguard.desc":`ルーターまたは VPN から提供された設定ファイルを貼り付けてください（[Interface] で始まります）。保管庫に保存されます。`,"browser.wireguard.config":`設定`,"browser.wireguard.kept":`保管庫に保存済みです。置き換えるには新しいものを貼り付けてください。`,"browser.wireguard.where":`Fritz!Box の場合：インターネット → 共有 → VPN（WireGuard）。OpenWrt の場合：インターフェースの WireGuard ピア。`,"browser.ts.s1":`ブラウザ用に Tailscale をインストール`,"browser.ts.s1done":`インストールしました（ブラウザ専用）。`,"browser.ts.s2":`Tailscaleにサインイン`,"browser.ts.s2desc":`無料アカウントです。スマートフォンでも同じアカウントを使います。`,"browser.ts.s2done":`サインイン済み：{account}`,"browser.ts.login":`サインイン`,"browser.ts.preparing":`サインインリンクを準備しています…`,"browser.ts.s3":`スマートフォンで`,"browser.ts.s3a":`1. Tailscaleをインストールします（右のQRコード）。`,"browser.ts.s3b":`2. 同じアカウントでサインインします。`,"browser.ts.s3c":`3. アプリで：Exit node → Run as exit node。`,"browser.ts.s3d":`4. オンのまま、充電しながら、Wi-Fiまたは4Gで放置してください。`,"browser.ts.s3e":`5. login.tailscale.com -> Machines で、出口を承認します：... -> Edit route settings -> Use as exit node。`,"browser.ts.unapproved":`{names} はオンラインですが、まだ出口として認識されていません。そこで「Run as exit node」がオンの場合は、Tailscaleコンソールでの承認が必要です（... -> Edit route settings -> Use as exit node）。`,"browser.ts.approve":`Tailscaleコンソールを開く`,"browser.ts.waitingPhone":`スマートフォンを待っています…`,"browser.ts.s4":`デバイスを選択`,"browser.ts.s4desc":`ページの通信が経由するデバイス：`,"browser.ts.nodeOffline":`このデバイスはオフラインです。デバイスでTailscaleを開いてください。`,"browser.ts.phone":`お使いのスマートフォン`,"browser.ts.qr.ios":`App StoreのTailscale`,"browser.ts.qr.android":`Google PlayのTailscale`,"browser.ts.good":`適した出口の条件`,"browser.ts.good1":`電源が入ったまま、充電されていること。`,"browser.ts.good2.ios":`Tailscaleアプリをバックグラウンドに残しておくこと（スワイプで終了しないでください）。`,"browser.ts.good2.android":`Tailscaleのバッテリー最適化をオフにすること。`,"browser.ts.good3":`自宅のWi-Fi、またはデータ容量が十分な4Gプラン。`,"browser.ts.headscale":`自分のHeadscaleサーバー`,"browser.ts.advanced":`詳細設定：Headscale`,"browser.ts.logout":`Tailscaleからサインアウト`};export{e as default};